import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class B {
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        out.println(solve(Math.min(R, C), Math.max(R, C)));
        out.close();
    }

    static long solve(long r, long c) {
        if (r < 3 && c < 3) return 0L;
        if (r == 1) {
            long m = c % 6;
            return c - Math.min(m, 6 - m);
        }
        if (r == 2) {
            if (c == 3 || c == 7) return 2L * (c - 1);
            return 2L * c;
        }
        return (r * c) & ~1L;
    }

    static class FS {
        BufferedReader br;
        StringTokenizer st;

        public FS() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw null;
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
